mapper.select:
select a.id, a.team_id, a.schedule_item_id, a.index_order, a.back_number, a.match_id, a.game_item_id, a.sport_limit, a.works_name, a.works_music, a.works_music_name, a.works_video,
a.create_time, a.update_time, b.id as sub_id, b.match_id as sub_match_id, b.sport_id as sub_sport_id, b.sign_record_id as sub_sign_record_id,
cc.player_name, cc.id_card, cc.sex
from jw_sign_record a
left join jw_sign_record_sport b on b.sign_record_id = a.id
left join jw_sport cc on cc.id = b.sport_id

    and a.team_id = #{teamId}
    and a.game_item_id = #{gameItemId}
    and a.back_number = #{backNumber}

mapper.update:
update jw_sign_record
team_id = #{teamId}, back_number = #{backNumber}, match_id = #{matchId}, game_item_id = #{gameItemId}, sport_limit = #{sportLimit}, works_name = #{worksName}, works_music = #{worksMusic}, works_music_name = #{worksMusicName}, works_video = #{worksVideo}, create_time = #{createTime}, update_time = #{updateTime}, schedule_item_id = #{scheduleItemId}, index_order = #{indexOrder},
where id = #{id}
